# Windows console is cp1252 by default; guide text frequently carries emoji / smart
# quotes. Reconfigure the stream to UTF-8 with replacement so a stray glyph can never
# raise UnicodeEncodeError and abort a long run.
try:
    _rc = getattr(sys.stdout, "reconfigure", None)
    if callable(_rc):
        _rc(encoding="utf-8", errors="replace")
    _rc2 = getattr(sys.stderr, "reconfigure", None)
    if callable(_rc2):
        _rc2(encoding="utf-8", errors="replace")
except Exception:
    pass

