VISION_URL = os.environ.get("HOJAIGA_QWEN_VL_URL",
                             os.environ.get("HOJAIGA_PROF_VISION_URL", "http://127.0.0.1:8081")).rstrip("/")
OLLAMA_URL = os.environ.get("HOJAIGA_PROF_OLLAMA_URL", "http://127.0.0.1:11434").rstrip("/")
VISION_MODEL = os.environ.get("HOJAIGA_VLM_NAME", "qwen3-vl")
SPLIT_SEED = int(os.environ.get("HOJAIGA_SPLIT_SEED", "7"))
TRAIN_RATIO = 0.70

# Real headers written by guide_extractor.py
COL_APP = "App Name"
COL_PUB = "Publisher"
COL_CAT = "COL_CATEGORY"          # resolved below
COL_GUIDE = "Guide Title"
COL_MD = "Guide Markdown"
COL_WORDS = "Word Count"
COL_STATUS = "Status"
COL_SPLIT = "Dataset_Split"
CATEGORY_HEADER = "Category"

MAX_GUIDE_CHARS = 12000           # bound what we hand to the model (context budget)
CHAT_TIMEOUT = 180.0
MAX_TOKENS = 3600

# A guide whose procedural-marker density is below this is descriptive (TOC, intro,
# changelog, privacy) -- it has no click/type steps to learn from. We skip it HONESTLY
# (status non_procedural) instead of burning a model call and logging a false "empty".
ACTION_FLOOR = int(os.environ.get("HOJAIGA_ACTION_FLOOR", "6"))

# Desktop-GUI signal: a guide is only a Phase-1 training target if it talks about
# on-screen widgets. CLI/web/server guides (sudo apt, curl, "click here" on a website)
# teach no desktop actuation, so they are rejected before the model, not after.
GUI_RX = re.compile(
    r"\b(?:menu|toolbar|ribbon|dialog|button|checkbox|tab|window|pane|field|textbox|"
    r"drop-?down|sidebar|pane|status bar|context menu|tool palette|canvas|workspace)\b", re.I)
CLI_RX = re.compile(r"\b(?:sudo|apt(?:-get)?|npm|pip|curl|wget|\bcd\b|terminal|command line|"
                    r"cli|docker|kubectl|\.sh\b|bash|api endpoint|http server)\b", re.I)

# Guide-page titles that never contain desktop click-steps, even when the body happens to
# mention a widget word. NOTE: a *manual* / *user guide* / *tutorial* is the MOST
# procedural document there is, so it must NOT be skipped -- only true navigational or
# legal boilerplate (TOC, releases, privacy) is, so a scraped README's TOC page is never
# chosen as an app's "best" guide.
NON_PROCEDURAL_TITLE_RX = re.compile(
    r"\b(?:table of contents|contents|releases?|changelog|change log|privacy|terms(?: of service)?|"
    r"license|licence|contributors|sponsors?|donate|donations|faq|readme|site index|security policy|"
    r"download|contact(?: us)?|sign in|log ?in|cookie policy)\b", re.I)


def log(msg: str) -> None:
    # A scraped guide title can contain emoji / non-cp1252 chars; the Windows console
    # defaults to cp1252 and raises UnicodeEncodeError mid-batch. Encode defensively so
    # one stray glyph never kills a long --ladder / --full run.
    text = f"[decompose] {msg}"
    try:
        print(text, flush=True)
    except UnicodeEncodeError:
        enc = getattr(sys.stdout, "encoding", None) or "ascii"
        safe = text.encode(enc, "replace").decode(enc, "replace")
        print(safe, flush=True)


def now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# --- Durability: keep Windows awake ONLY while the corpus run is active ------
# A laptop in Modern Standby (S0) / S3 sleep kills the background run mid-way. This
# in-process SetThreadExecutionState lock prevents sleep during the run and is released
# automatically on exit (atexit + OS clears it if the process is force-killed), so normal
# power management resumes the instant the run ends. No permanent battery drain.
PHASE1_MARKER = BRAIN_DIR / "phase1_run.json"


def _acquire_wake_lock() -> None:
    if os.name != "nt":
        return
    try:
        import ctypes
        import atexit
        ES_CONTINUOUS, ES_SYSTEM_REQUIRED, ES_AWAYMODE_REQUIRED = 0x80000000, 0x00000001, 0x00000040
        k32 = ctypes.windll.kernel32
        if not k32.SetThreadExecutionState(ES_CONTINUOUS | ES_SYSTEM_REQUIRED | ES_AWAYMODE_REQUIRED):
            k32.SetThreadExecutionState(ES_CONTINUOUS | ES_SYSTEM_REQUIRED)   # awaymode unsupported
        atexit.register(lambda: k32.SetThreadExecutionState(ES_CONTINUOUS))
    except Exception:
        pass


def _write_completion_marker(counts: dict, rows_walked: int, dur: float) -> None:
    try:
        PHASE1_MARKER.parent.mkdir(parents=True, exist_ok=True)
        PHASE1_MARKER.write_text(json.dumps(
            {"complete": True, "counts": counts, "rows_walked": rows_walked,
             "duration_s": dur, "finished": now_iso()}, ensure_ascii=False, indent=3), encoding="utf-8")
    except Exception:
        pass


# ---------------------------------------------------------------------------
# Normalisation helpers
# ---------------------------------------------------------------------------

def app_key_of(name: str) -> str:
    k = re.sub(r"\.exe$", "", (name or "").strip().lower())
    k = re.sub(r"[^a-z0-9]+", "_", k).strip("_")
    return k or "app"


def slug_of(text: str, n: int = 60) -> str:
    s = re.sub(r"[^a-z0-9]+", "_", (text or "").strip().lower()).strip("_")
    return s[:n] or "guide"


def cell_str(v) -> str:
    """Coerce any openpyxl cell value (str/number/date/rich-text) to a clean string."""
    if v is None:
        return ""
    if isinstance(v, str):
        return v.strip()
    try:
        return str(v).strip()
    except Exception:
        return ""


import hashlib


def content_hash(md: str) -> str:
    return hashlib.sha1((md or "").encode("utf-8", "replace")).hexdigest()[:12]


# Generic aggregator / non-app keys that would otherwise dominate a word-count
# ranking (docs portals, boilerplate pages). Never good decomposition targets.
GENERIC_APP_KEYS = {
    "app", "apps", "guide", "guides", "home", "support", "index", "documentation",
    "docs", "doc", "terms", "privacy", "about", "contact", "download", "product",
    "help", "faq", "news", "blog", "store", "welcome", "overview",
}

# Representative, genuinely complex desktop apps. Used only to SEED a pilot batch
# (overridable with --apps); this is an operator choice of what to eyeball, not
# generated data. Matched by case-insensitive substring against the corpus.
PILOT_HINT_APPS = [
    "microsoft word", "word", "excel", "powerpoint", "notepad", "paint",
    "blender", "gimp", "inkscape", "krita", "vlc", "firefox", "chrome",
    "libreoffice", "audacity", "obs studio", "obs", "pdf", "notepad++",
]


def is_real_title(title: str) -> bool:
    t = (title or "").strip()
    if len(t) < 4:
        return False
    if re.fullmatch(r"[0-9a-f]{8,}", t.lower()):   # pure hash slug
        return False
    if re.fullmatch(r"[0-9_.\-]+", t):               # pure number / version
        return False
    return True


def as_int(v, default: int = 0) -> int:
    try:
        return int(v)
    except (TypeError, ValueError):
        return default


# Procedural markers: how step-by-step / actionable a guide is. Guides rich in
# these are the ones worth decomposing; long-but-prose pages (privacy, changelog)
# score low and sink to the bottom so compute goes where real trajectories exist.
ACTION_RX = re.compile(
    r"\b(?:click|select|choose|press|tap|type|enter|open the|go to|check the|"
    r"ribbon|tab|menu|toolbar|dialog|button|field|checkbox)\b|\d+\.|step \d", re.I)


def action_score(md: str) -> int:
    return len(ACTION_RX.findall(md or ""))


# ---------------------------------------------------------------------------
# Load the guide corpus
# ---------------------------------------------------------------------------

def load_rows() -> list[dict]:
    if not EXCEL_FILE.exists():
        log(f"ERROR: workbook not found: {EXCEL_FILE.resolve()}")
        log("Run guide_extractor.py first to build the corpus.")
        sys.exit(2)
    wb = load_workbook(EXCEL_FILE, read_only=True, data_only=True)
    if SHEET_NAME not in wb.sheetnames:
        log(f"ERROR: sheet '{SHEET_NAME}' not in workbook ({wb.sheetnames})")
        sys.exit(2)
    ws = wb[SHEET_NAME]
    it = ws.iter_rows(values_only=True)
    header = [str(h).strip() if h is not None else "" for h in next(it)]
    idx = {name: i for i, name in enumerate(header)}
    for required in (COL_APP, COL_MD):
        if required not in idx:
            log(f"ERROR: expected column '{required}' not found; header={header}")
            sys.exit(2)

    rows: list[dict] = []
    for raw in it:
        if raw is None:
            continue
        app = cell_str(raw[idx[COL_APP]]) if idx[COL_APP] < len(raw) else ""
        md = raw[idx[COL_MD]] if idx[COL_MD] < len(raw) else None
        if not app or not md:
            continue
        cat = cell_str(raw[idx[CATEGORY_HEADER]]) if CATEGORY_HEADER in idx and idx[CATEGORY_HEADER] < len(raw) else ""
        rows.append({
            "app_name": app,
            "app_key": app_key_of(app),
            "publisher": cell_str(raw[idx[COL_PUB]]) if COL_PUB in idx and idx[COL_PUB] < len(raw) else "",
            "category": cat,
            "guide_title": cell_str(raw[idx[COL_GUIDE]]) if COL_GUIDE in idx and idx[COL_GUIDE] < len(raw) else "",
            "markdown": str(md),
            "md_path": cell_str(raw[idx["MD Path"]]) if "MD Path" in idx and idx["MD Path"] < len(raw) else "",
            "word_count": as_int(raw[idx[COL_WORDS]]) if COL_WORDS in idx and idx[COL_WORDS] < len(raw) else len(str(md).split()),
            "status": cell_str(raw[idx[COL_STATUS]]) if COL_STATUS in idx and idx[COL_STATUS] < len(raw) else "",
            "action_score": action_score(str(md)),
        })
    wb.close()
    log(f"Loaded {len(rows)} guide rows across {len(set(r['app_key'] for r in rows))} apps.")
    return rows


# ---------------------------------------------------------------------------
# App-level 70/30 split
# ---------------------------------------------------------------------------

def build_split(rows: list[dict]) -> dict:
    """Deterministically assign each distinct app to TRAIN or EVAL. Cached in MANIFEST_FILE."""
    if MANIFEST_FILE.exists():
        try:
            mf = json.loads(MANIFEST_FILE.read_text(encoding="utf-8"))
            if mf.get("apps"):
                log(f"Using existing split manifest: {len(mf['apps'])} apps "
                    f"({sum(1 for v in mf['apps'].values() if v.get('split')=='TRAIN')} TRAIN / "
                    f"{sum(1 for v in mf['apps'].values() if v.get('split')=='EVAL')} EVAL).")
                return mf
        except Exception:
            log("Split manifest unreadable; rebuilding.")

    apps: dict[str, dict] = {}
    for r in rows:
        apps.setdefault(r["app_key"], {"app_name": r["app_name"], "words": 0, "category": r["category"]})
        apps[r["app_key"]]["words"] += r["word_count"]

    keys = sorted(apps)
    rng = random.Random(SPLIT_SEED)
    rng.shuffle(keys)
    n_train = int(round(len(keys) * TRAIN_RATIO))
    for i, k in enumerate(keys):
        apps[k]["split"] = "TRAIN" if i < n_train else "EVAL"

    mf = {"seed": SPLIT_SEED, "train_ratio": TRAIN_RATIO, "created": now_iso(),
          "counts": {"TRAIN": n_train, "EVAL": len(keys) - n_train}, "apps": apps}
    TRAJ_DIR.mkdir(parents=True, exist_ok=True)
    MANIFEST_FILE.write_text(json.dumps(mf, ensure_ascii=False, indent=3), encoding="utf-8")
    log(f"Assigned app-level split: {n_train} TRAIN / {len(keys) - n_train} EVAL -> {MANIFEST_FILE}")
    return mf


def write_excel_split(rows: list[dict], manifest: dict) -> None:
    """One-time heavy op: add / refresh the Dataset_Split column in the workbook."""
    log("Adding Dataset_Split column to the workbook (one-time; loads full workbook)...")
    wb = load_workbook(EXCEL_FILE)
    ws = wb[SHEET_NAME]
    header = [str(c.value).strip() if c.value is not None else "" for c in ws[1]]
    if COL_SPLIT in header:
        col = header.index(COL_SPLIT) + 1
    else:
        col = len(header) + 1
        ws.cell(row=1, column=col, value=COL_SPLIT)
        from openpyxl.styles import Font, PatternFill
        c = ws.cell(row=1, column=col)
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="2F5597")
    app_col = header.index(COL_APP) + 1
    n = 0
    for r in range(2, ws.max_row + 1):
        app = ws.cell(row=r, column=app_col).value
        if not app:
            continue
        sp = manifest["apps"].get(app_key_of(str(app)), {}).get("split", "")
        ws.cell(row=r, column=col, value=sp)
        n += 1
    wb.save(EXCEL_FILE)
    log(f"Wrote Dataset_Split to {n} rows in column {col}.")


# ---------------------------------------------------------------------------
# Local model client (text brain first, vision eyes as fallback)
#
# Corpus decomposition is a pure-text extraction job. The resident instruct text
# model (Ollama) is fast and reliable at emitting the JSON array; the Qwen3-VL
# vision server (:8081) is the runtime "eyes" for screen grounding and is slow /
# weak at long text-JSON generation (it times out). So the default order here is
# Ollama first, vision only as a backup. Override with --engine.
# ---------------------------------------------------------------------------

def _extract_json(text: str):
    t = (text or "").strip()
    t = re.sub(r"^```(?:json)?\s*|\s*```$", "", t, flags=re.I)
    try:
        return json.loads(t)
    except Exception:
        pass
    a, b = t.find("{"), t.rfind("}")
    if 0 <= a < b:
        try:
            return json.loads(t[a:b + 1])
        except Exception:
            return None
    return None


def _post_json(url: str, payload: dict) -> str | None:
    try:
        r = requests.post(url, json=payload, timeout=CHAT_TIMEOUT)
        r.raise_for_status()
        data = r.json()
    except Exception as exc:
        log(f"  model call failed ({url}): {type(exc).__name__}: {str(exc)[:120]}")
        return None
    try:
        return (data["choices"][0]["message"]["content"] or "")
    except Exception:
        try:
            return (data.get("message") or {}).get("content", "")
        except Exception:
            return None


ENGINE = os.environ.get("HOJAIGA_DECOMPOSE_ENGINE", "auto")   # auto | ollama | vision


def _engine_order() -> list[str]:
    if ENGINE == "ollama":
        return ["ollama"]
    if ENGINE == "vision":
        return ["vision", "ollama"]
    return ["ollama", "vision"]        # auto: text brain first


def _call_engine(engine: str, system: str, user: str) -> str | None:
    """Return raw model text for one engine, or None on transport failure."""
    msgs = [{"role": "system", "content": system}, {"role": "user", "content": user}]
    if engine == "ollama":
        return _post_json(OLLAMA_URL + "/api/chat", {
            "model": _discover_ollama(), "stream": False, "format": "json",
            "options": {"temperature": 0.0, "num_predict": MAX_TOKENS, "num_ctx": 8192},
            "messages": msgs,
        })
    return _post_json(VISION_URL + "/v1/chat/completions", {
        "model": VISION_MODEL, "temperature": 0.0, "max_tokens": MAX_TOKENS,
        "messages": msgs,
    })


def generate_trajectories(app_name: str, category: str, split: str, markdown: str):
    """Ask the local model to convert one guide into the standard trajectory JSON.

    Returns (json_obj|None, status_str). The JSON is whatever the model produced;
    nothing here is hard-coded. Engines are tried in order; we fall through only
    on transport/parse failure, never on an honest empty trajectory."""
    system = SYSTEM_PROMPT_TEMPLATE.format(app_name=app_name)
    user = (
        f"TARGET_APPLICATION: {app_name}\n"
        f"CATEGORY: {category or 'unknown'}\n"
        f"DATASET_SPLIT: {split}\n\n"
        f"APP_GUIDE_EXCERPT:\n{markdown[:MAX_GUIDE_CHARS]}\n\n"
        "Return ONLY the JSON object for this one guide."
    )

    got_text = False
    for engine in _engine_order():
        content = _call_engine(engine, system, user)
        if content is None:
            continue
        got_text = True
        obj = _extract_json(content)
        if obj is not None:
            return obj, f"{engine}:{VISION_MODEL if engine=='vision' else _discover_ollama()}"
    return None, ("no_json" if got_text else "model_down")


_ollama_model = None


def _discover_ollama() -> str:
    global _ollama_model
    if _ollama_model:
        return _ollama_model
    pref = ("qwen2.5:7b", "qwen2.5", "qwen3", "llama3.1", "llama3")
    try:
        tags = requests.get(OLLAMA_URL + "/api/tags", timeout=5).json()
        models = [m.get("name", "") for m in tags.get("models", []) if "embed" not in m.get("name", "").lower()]
    except Exception:
        models = []
    for want in pref:
        for m in models:
            if m.lower().startswith(want):
                _ollama_model = m
                return m
    _ollama_model = models[0] if models else "qwen2.5:7b"
    return _ollama_model


def model_up() -> bool:
    """Cheap reachability probe so we fail loudly before a long run, not silently."""
    try:
        requests.get(VISION_URL + "/v1/models", timeout=5)
        return True
    except Exception:
        pass
    try:
        requests.get(OLLAMA_URL + "/api/tags", timeout=5)
        return True
    except Exception:
        return False


# ---------------------------------------------------------------------------
# Schema guard (light: reject non-action output, do NOT invent missing fields)
# ---------------------------------------------------------------------------

def validate(obj: dict) -> list[str]:
    warn = []
    if not isinstance(obj, dict):
        return ["not_an_object"]
    kind = str(obj.get("target_kind") or "").lower()
    traj = obj.get("trajectory")
    if not isinstance(traj, list) or not traj:
        # An empty trajectory is CORRECT (not a defect) when the model judged the guide
        # non-desktop-GUI. Only flag empties that claim to be desktop_gui.
        if kind not in ("cli", "web", "non_gui"):
            warn.append("empty_or_missing_trajectory")
    else:
        for i, step in enumerate(traj, 1):
            if not isinstance(step, dict):
                warn.append(f"step{i}_not_object")
                continue
            if "virtual_mouse_action" not in step and "action" not in step:
                warn.append(f"step{i}_no_action")
            if "expected_state_change" not in step:
                warn.append(f"step{i}_no_expected_state_change")
            ut = step.get("ui_target") or {}
            if not (ut.get("element_name") or ut.get("automation_id") or ut.get("hierarchical_path")):
                warn.append(f"step{i}_ungrounded_target")
    if "high_level_task" not in obj:
        warn.append("no_high_level_task")
    return warn


# ---------------------------------------------------------------------------
# Pilot selection: a small, diverse, deliberately complex batch
# ---------------------------------------------------------------------------

def select_pilot(rows: list[dict], n_apps: int, explicit: list[str] | None) -> set[str]:
    if explicit:
        want = {app_key_of(a) for a in explicit}
        have = {r["app_key"] for r in rows}
        missing = [a for a, k in zip(explicit, want) if k not in have]
        if missing:
            log(f"NOTE: explicit apps not in corpus: {missing}")
        return want & have

    # Only trust guides with a real title; ignore generic aggregator docs portals.
    good = [r for r in rows
            if r["app_key"] not in GENERIC_APP_KEYS and is_real_title(r["guide_title"])]
    best_act: dict[str, int] = {}         # app -> its most procedural real guide
    name_of: dict[str, str] = {}
    for r in good:
        best_act[r["app_key"]] = max(best_act.get(r["app_key"], 0), r["action_score"])
        name_of.setdefault(r["app_key"], r["app_name"])

    chosen: list[str] = []
    used: set[str] = set()

    # 1) Seed with representative complex apps that are actually present.
    for hint in PILOT_HINT_APPS:
        if len(chosen) >= n_apps:
            break
        for k, nm in name_of.items():
            if k not in used and hint in nm.lower():
                chosen.append(k)
                used.add(k)
                break

    # 2) Top up by most procedural guide (action density, not raw length).
    if len(chosen) < n_apps:
        for k in sorted(best_act, key=lambda x: -best_act[x]):
            if k in used:
                continue
            chosen.append(k)
            used.add(k)
            if len(chosen) >= n_apps:
                break

    log(f"Pilot apps: {[name_of.get(k, k) for k in chosen]}")
    return set(chosen)


# ---------------------------------------------------------------------------
# Guide classification + difficulty ladder (Phase-1 training selection)
# ---------------------------------------------------------------------------

def is_desktop_gui(md: str) -> bool:
    """A guide is a usable Phase-1 target only if it references on-screen widgets and is
    not dominated by command-line / web-server instructions. Rejects the 'sudo apt-get'
    class of guides that produce null-ui_target trajectories before they reach the model."""
    s = md or ""
    gui = len(GUI_RX.findall(s))
    cli = len(CLI_RX.findall(s))
    return gui >= 2 and gui >= cli


def complexity_score(row: dict) -> int:
    """Difficulty proxy for an app's best guide: procedural density + widget breadth +
    length. Ranks Notepad/Calculator low and Blender/VS Code/OBS high, so a ladder can
    span easy -> hard. This is a SELECTION heuristic, not generated data."""
    md = row.get("markdown", "") or ""
    uniq_widgets = len({m.lower() for m in GUI_RX.findall(md)})
    return int(row.get("action_score", 0)) + 3 * uniq_widgets + min(len(md) // 800, 40)


def best_guide_per_app(rows: list[dict]) -> dict:
    """app_key -> its single most-procedural DESKTOP-GUI guide (or None if the app has no
    GUI guide). Decomposing only this guide per app is what removes the TOC/description
    'empty' noise: we no longer spend a model call on every non-actionable page."""
    best: dict[str, dict] = {}
    for r in rows:
        if r["app_key"] in GENERIC_APP_KEYS or not is_real_title(r["guide_title"]):
            continue
        if NON_PROCEDURAL_TITLE_RX.search(r["guide_title"] or ""):
            continue
        if not is_desktop_gui(r["markdown"]) or r["action_score"] < ACTION_FLOOR:
            continue
        cur = best.get(r["app_key"])
        if cur is None or r["action_score"] > cur["action_score"]:
            best[r["app_key"]] = r
    return best


def select_ladder(rows: list[dict], n_apps: int) -> list[tuple]:
    """Pick n_apps GUI-capable apps spanning easy -> hard by complexity quartile, so the
    pilot trains on a varied spread (Notepad-like -> Blender-like) instead of only easy or
    only hard. Returns [(app_key, app_name, tier_label, complexity)] ordered easy -> hard."""
    best = best_guide_per_app(rows)
    scored = sorted(((k, cs) for k, r in best.items() for cs in [complexity_score(r)]),
                    key=lambda x: x[1])
    if not scored:
        return []
    q = len(scored) / 4.0
    tiers = ["easy", "moderate", "complex", "very-complex"]
    buckets: list[list] = [[], [], [], []]
    for idx, (k, cs) in enumerate(scored):
        buckets[min(3, int(idx / q))].append((k, cs))
    picks: list[tuple] = []
    per = max(1, n_apps // 4)
    for ti, bk in enumerate(buckets):
        take = bk[:per] if ti < 3 else bk
        for k, cs in take:
            picks.append((k, best[k]["app_name"], tiers[ti], cs))
    picks.sort(key=lambda x: x[3])
    return picks[:n_apps]


# ---------------------------------------------------------------------------
# Continuous ML ingestion (TRAIN-only; identical grounded-only rule as the batch builder)
# ---------------------------------------------------------------------------

def load_seen_sample_ids() -> set:
    """Existing sample_ids so a resumed / --force run never double-appends a step."""
    seen: set = set()
    if _sample_from_step is None or not TRAIN_SAMPLES.exists():
        return seen
    try:
        with TRAIN_SAMPLES.open(encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    sid = json.loads(line).get("sample_id")
                    if sid:
                        seen.add(sid)
                except Exception:
                    continue
    except Exception:
        pass
    return seen


def ingest_trajectory_samples(app_key: str, obj: dict, split: str, seen: set) -> int:
    """Append this trajectory's grounded TRAIN samples to train_samples.jsonl live.
    Returns how many NEW samples were written. EVAL trajectories are NEVER ingested
    (leakage rule) -- they stay on disk for the Phase-2 queue only."""
    if _sample_from_step is None or split != "TRAIN" or not isinstance(obj, dict):
        return 0
    traj = obj.get("trajectory") or []
    new = []
    for step in traj:
        if not isinstance(step, dict):
            continue
        s = _sample_from_step(app_key, obj, step, require_grounding=True)
        if not s or s["sample_id"] in seen:
            continue
        seen.add(s["sample_id"])
        new.append(s)
    if not new:
        return 0
    try:
        BRAIN_DIR.mkdir(parents=True, exist_ok=True)
        with TRAIN_SAMPLES.open("a", encoding="utf-8") as fh:
            for s in new:
                fh.write(json.dumps(s, ensure_ascii=False) + "\n")
    except Exception as exc:
        log(f"  ingest write failed: {type(exc).__name__}: {str(exc)[:60]}")
        return 0
    return len(new)


# ---------------------------------------------------------------------------
# Main decomposition loop
# ---------------------------------------------------------------------------

def run(args) -> None:
    _acquire_wake_lock()                       # keep the box awake for the whole run
    try:                                       # clear any stale completion marker up front
        if PHASE1_MARKER.exists():
            PHASE1_MARKER.unlink()
    except Exception:
        pass
    if args.engine:
        global ENGINE
        ENGINE = args.engine
        log(f"Engine override: {ENGINE}")
    rows = load_rows()
    manifest = build_split(rows)

    if args.assign_split and not (args.full or args.pilot or args.apps):
        if args.write_excel_split:
            write_excel_split(rows, manifest)
        log("Split assignment complete (no decomposition requested).")
        return

    if args.write_excel_split:
        write_excel_split(rows, manifest)

    best_only = not args.full
    if args.full:
        chosen = None
        log("FULL run: decomposing every guide (non-GUI / non-procedural pages skipped honestly).")
    elif args.ladder:
        ladder = select_ladder(rows, args.ladder)
        chosen = {k for k, _n, _t, _c in ladder}
        for k, nm, tier, cs in ladder:
            log(f"  ladder[{tier:12s}] {nm}  (complexity {cs})")
        log(f"LADDER run: {len(chosen)} apps spanning easy -> hard.")
    else:
        n = args.pilot if args.pilot else 5
        chosen = select_pilot(rows, n, args.apps.split(",") if args.apps else None)
        log(f"PILOT run: decomposing {len(chosen)} apps. Use --full to unleash the corpus.")

    # Build the exact list of guides to decompose. In pilot/ladder mode we take only each
    # chosen app's single most-procedural DESKTOP-GUI guide, so TOC/description/CLI pages
    # never burn a model call or land as a false 'empty'. --full walks every row but still
    # rejects non-GUI / below-floor pages up front (status non_procedural, not a failure).
    if best_only:
        best = best_guide_per_app(rows)
        todo = [r for k, r in best.items() if chosen is None or k in chosen]
    else:
        todo = rows

    if not args.dry_run and not model_up():
        log("ERROR: no local model reachable (Qwen3-VL :8081 or Ollama :11434).")
        log("Start the vision server (python hojaiga_professor.py server start) or Ollama, then retry.")
        sys.exit(3)

    TRAJ_DIR.mkdir(parents=True, exist_ok=True)
    counts = {"generated": 0, "no_json": 0, "model_down": 0, "skipped_exist": 0,
              "non_procedural": 0, "warned": 0, "ingested": 0}
    seen_samples = load_seen_sample_ids()
    if _sample_from_step is None:
        log("NOTE: continuous ML ingestion OFF (phase1_training_dataset sampler not importable).")
    else:
        log(f"Continuous ML ingestion ON -> {TRAIN_SAMPLES} (TRAIN-only, {len(seen_samples)} existing samples deduped)")
    t0 = time.time()
    logfh = RUN_LOG.open("a", encoding="utf-8")

    for r in todo:
        if chosen is not None and r["app_key"] not in chosen:
            continue
        split = manifest["apps"].get(r["app_key"], {}).get("split", "TRAIN")
        out_dir = TRAJ_DIR / split / r["app_key"]
        # unique per guide: readable title slug + content hash so empty/duplicate
        # titles never overwrite each other.
        base = slug_of(r["guide_title"] or Path(r["md_path"]).stem or r["app_name"])
        out_file = out_dir / f"{base}__{content_hash(r['markdown'])}.json"
        if out_file.exists() and not args.force:
            counts["skipped_exist"] += 1
            continue
        # Honest rejection BEFORE the model: a --full pass still meets descriptive or
        # CLI/web pages that carry no desktop click-steps; log them, don't fake a trajectory.
        if not best_only and (not is_desktop_gui(r["markdown"]) or r["action_score"] < ACTION_FLOOR):
            counts["non_procedural"] += 1
            logfh.write(json.dumps({"ts": now_iso(), "app": r["app_name"], "app_key": r["app_key"],
                                    "split": split, "guide": r["guide_title"],
                                    "status": "non_procedural", "steps": 0}, ensure_ascii=False) + "\n")
            log(f"  non_procedural {r['app_name']} :: {r['guide_title'][:40]} (skipped, no model call)")
            continue
        if args.dry_run:
            log(f"[dry] would generate {split}/{r['app_key']}/{out_file.name}")
            continue

        obj, status = generate_trajectories(r["app_name"], r["category"], split, r["markdown"])
        # Throttle ONLY after a real inference call (success or failure), never on the
        # cache-hit / dry-run `continue` paths above, so resumed runs skip finished guides
        # at full speed while a live pass keeps sustained GPU/CPU load from thermal-throttling.
        if args.throttle_ms > 0:
            time.sleep(args.throttle_ms / 1000.0)
        rec = {"ts": now_iso(), "app": r["app_name"], "app_key": r["app_key"], "split": split,
               "guide": r["guide_title"], "status": status, "file": str(out_file)}
        if obj is None:
            counts[status if status in counts else "no_json"] = counts.get(status, 0) + 1
            rec["steps"] = 0
            logfh.write(json.dumps(rec, ensure_ascii=False) + "\n")
            log(f"  {status:12s} {r['app_name']} :: {r['guide_title'][:40]}")
            continue

        warn = validate(obj)
        record = obj if isinstance(obj, dict) else {"raw": obj}
        record["_meta"] = {
            "source_app": r["app_name"], "app_key": r["app_key"], "dataset_split": split,
            "category": r["category"], "guide_title": r["guide_title"], "source_status": r["status"],
            "generator": status, "produced": now_iso(), "schema_warnings": warn,
            "note": "trajectory JSON produced by the local model; verify against live UIA before caching",
        }
        out_dir.mkdir(parents=True, exist_ok=True)
        out_file.write_text(json.dumps(record, ensure_ascii=False, indent=3), encoding="utf-8")
        counts["generated"] += 1
        if warn:
            counts["warned"] += 1
        # Live ML ingestion: append this trajectory's grounded TRAIN samples now, so the
        # model keeps ingesting across the multi-hour run instead of only on a rebuild pass.
        ing = ingest_trajectory_samples(r["app_key"], obj, split, seen_samples)
        if ing:
            counts["ingested"] += ing
        rec["steps"] = len(record.get("trajectory", [])) if isinstance(record, dict) else 0
        rec["warnings"] = warn
        rec["ingested_samples"] = ing
        logfh.write(json.dumps(rec, ensure_ascii=False) + "\n")
        log(f"  generated   {r['app_name']} :: {r['guide_title'][:40]} "
            f"({rec['steps']} steps, +{ing} ingested{' WARN:' + ','.join(warn) if warn else ''})")

    logfh.close()
    dur = round(time.time() - t0, 1)
    log(f"DONE in {dur}s -> {json.dumps(counts)}")
    log(f"Outputs under {TRAJ_DIR.resolve()} ; run log: {RUN_LOG}")
    _write_completion_marker(counts, len(todo), dur)   # watchdog reads this to stop relaunching


# ---------------------------------------------------------------------------
# Strict extraction prompt (schema from the architecture blueprint).
# This is a PROMPT, not generated data: the model produces the JSON.
# ---------------------------------------------------------------------------

SYSTEM_PROMPT_TEMPLATE = """You are the Central Task Decomposition and Action Planning Engine for an autonomous \
desktop automation system. You convert ONE software-manual guide into a strictly structured Action-State \
Trajectory JSON. Your CORE JOB is to extract every concrete instruction the guide already states and turn \
each one into a trajectory step. Restating the guide's own steps is REQUIRED, not invention. Only forbid \
yourself from adding features, buttons or menu items the guide never mentions. Emit an empty trajectory \
array ONLY when the guide is purely descriptive (no imperative how-to actions at all). When the guide has \
numbered or imperative steps ("click", "select", "type", "open", "go to", "press", numbered lists), you \
MUST produce one trajectory step for each, never an empty array. Every step specifies how the virtual mouse \
performs it and what confirms success.

FIRST classify the guide with a top-level "target_kind":
- "desktop_gui": it operates an on-screen desktop application (menus, buttons, toolbars, dialogs, fields).
- "cli": it is command-line / terminal / package-manager only (sudo, apt, npm, docker, curl, scripts).
- "web": it walks a website / browser page, not a desktop app window.
- "non_gui": anything else with no interactive widgets.
If target_kind is NOT "desktop_gui", emit an EMPTY trajectory array (a CLI/web guide teaches no desktop \
actuation and must not pollute the training set). When it IS "desktop_gui", every step MUST fill \
ui_target.element_name and ui_target.element_type from the guide's own widget wording -- never null.

Target application: {app_name}

Virtual mouse & input capabilities (action_type must be one of these):
- "CLICK", "RIGHT_CLICK", "DOUBLE_CLICK", "HOVER"  (single coordinate target [x, y])
- "DRAG_AND_DROP" (press at start, move, release at end)
- "CONTINUOUS_DRAG" (hold a button through an ordered array of coordinate waypoints; canvas/Paint strokes, 3D orbit)
- "TYPE_TEXT" (string into the focused element)
- "KEY_COMBINATION" (shortcut sequence, e.g. ["Ctrl","S"])

Output ONLY valid JSON, no prose, matching exactly this schema:
{{
  "app_metadata": {{
    "app_name": "Target Application Name",
    "dataset_split": "TRAIN or EVAL",
    "scan_prerequisites_met": true
  }},
  "target_kind": "desktop_gui | cli | web | non_gui",
  "high_level_task": "Concise restatement of the objective this guide achieves",
  "prerequisite_state": "The exact application / document / window state required before Step 1",
  "total_steps": 0,
  "trajectory": [
    {{
      "step_id": 1,
      "low_level_instruction": "Human-readable description of this micro-action",
      "ui_target": {{
        "element_name": "Label or identifier from the guide",
        "automation_id": null,
        "hierarchical_path": "e.g. Ribbon > Group > Button (or null)",
        "element_type": "Button | Canvas | MenuItem | TextBox | Slider | Tab | ListItem",
        "bounding_box": [0, 0, 0, 0]
      }},
      "virtual_mouse_action": {{
        "action_type": "CLICK | RIGHT_CLICK | DOUBLE_CLICK | HOVER | DRAG_AND_DROP | CONTINUOUS_DRAG | TYPE_TEXT | KEY_COMBINATION",
        "coordinates": {{"x": 0, "y": 0}},
        "path_waypoints": [[0, 0], [0, 0]],
        "button": "left | right | middle | none",
        "modifiers": [],
        "text_payload": null
      }},
      "expected_state_change": "The exact visual or structural difference that confirms this step succeeded"
    }}
  ]
}}

Rules:
- Set "total_steps" to len(trajectory).
- Use null for coordinates / path_waypoints / text_payload when not applicable.
- bounding_box must be [left, top, right, bottom]; use [0,0,0,0] when unknown (the live scanner fills it later).
- Keep element_name / low_level_instruction grounded in the guide's own wording.
- Prefer a short click/type/shortcut step over vague narration.

Worked example (shape only - fictional app, NOT the target):
{{
  "app_metadata": {{"app_name": "ExampleApp", "dataset_split": "TRAIN", "scan_prerequisites_met": true}},
  "high_level_task": "Create a new document",
  "prerequisite_state": "ExampleApp is open on its start screen",
  "total_steps": 2,
  "trajectory": [
    {{
      "step_id": 1,
      "low_level_instruction": "Open the File menu",
      "ui_target": {{"element_name": "File", "automation_id": null, "hierarchical_path": "Menu bar > File", "element_type": "MenuItem", "bounding_box": [0, 0, 0, 0]}},
      "virtual_mouse_action": {{"action_type": "CLICK", "coordinates": {{"x": 0, "y": 0}}, "path_waypoints": null, "button": "left", "modifiers": [], "text_payload": null}},
      "expected_state_change": "The File dropdown opens showing New, Open, Save"
    }},
    {{
      "step_id": 2,
      "low_level_instruction": "Choose New",
      "ui_target": {{"element_name": "New", "automation_id": null, "hierarchical_path": "Menu bar > File > New", "element_type": "MenuItem", "bounding_box": [0, 0, 0, 0]}},
      "virtual_mouse_action": {{"action_type": "CLICK", "coordinates": {{"x": 0, "y": 0}}, "path_waypoints": null, "button": "left", "modifiers": [], "text_payload": null}},
      "expected_state_change": "A blank untitled document appears in the workspace"
    }}
  ]
}}

Now decompose the TARGET guide handed in. Output ONLY the JSON object, no prose.
"""


def build_argparser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="Decompose the app-guide corpus into action-state trajectory JSON.")
    p.add_argument("--pilot", type=int, default=0, help="number of complex, diverse apps for a pilot batch (default 5)")
    p.add_argument("--ladder", type=int, default=0, help="pick N GUI-capable apps spanning easy->hard (difficulty ladder)")
    p.add_argument("--apps", type=str, default="", help="comma-separated explicit app names to decompose")
    p.add_argument("--full", action="store_true", help="decompose the entire corpus (slow; only after pilot is flawless)")
    p.add_argument("--assign-split", action="store_true", help="ensure the Dataset_Split manifest exists")
    p.add_argument("--write-excel-split", action="store_true", help="add/refresh the Dataset_Split column in the xlsx (one-time, heavy)")
    p.add_argument("--force", action="store_true", help="regenerate even if the output JSON already exists")
    p.add_argument("--engine", choices=["auto", "ollama", "vision"], default=None,
                   help="model to decompose with (default auto: Ollama text model first, Qwen3-VL backup)")
    p.add_argument("--dry-run", action="store_true", help="list what would be generated without calling the model")
    p.add_argument("--throttle-ms", type=int, default=100,
                   help="delay in ms AFTER each real LLM inference call (0=off); prevents thermal/VRAM throttling over a --full pass. Cache-hit skips are not delayed.")
    return p


if __name__ == "__main__":
    run(build_argparser().parse_args())
